 function whistle(){if(!context||paused||!active||muted||volume===0)return;const s=context.createOscillator(),g=context.createGain(),t=context.currentTime;s.type='triangle';s.frequency.setValueAtTime(2320,t);s.frequency.linearRampToValueAtTime(2540,t+.12);s.frequency.linearRampToValueAtTime(2350,t+.28);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.035,t+.025);g.gain.exponentialRampToValueAtTime(.0001,t+.32);s.connect(g);g.connect(master);effects.add(s);s.start(t);s.stop(t+.34);s.onended=()=>{effects.delete(s);s.disconnect();g.disconnect();};}
